mapper.select:
SELECT * FROM poi
WHERE status = 1

    AND category = #{category}

AND (6371 * acos(
    cos(radians(#{latitude})) * cos(radians(lat)) *
    cos(radians(lng) - radians(#{longitude})) +
    sin(radians(#{latitude})) * sin(radians(lat))
)) <= #{radius}
ORDER BY rating DESC
LIMIT #{limit}
